INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(21901, 'Zechariah 9:17', 'Zechariah', 9, 17, '&nbsp;هغوئ به څومره ښکلې او ښائسته وى. غله به ځوانان سړى، او نوى مے به ځوانې ښځې څربه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21902, 'Zechariah 10:1', 'Zechariah', 10, 1, '&nbsp;مالِک خُدائ ته په سپرلى کښې د باران دپاره سوال وکړئ. ځکه چې دا مالِک خُدائ دے چې طوفانى وريځې رالېږى. هغه باران ورَوى او د هر چا دپاره په پټو کښې شنۀ بوټى پېدا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21903, 'Zechariah 10:2', 'Zechariah', 10, 2, '&nbsp;بُتان د فريب خبرې کوى، فالګر هغه رويا ګورى چې دروغ وى، هغوئ د خوبونو غلط تعبير کوى، او هغوئ بې‌فائدې تسلى ورکوى. نو ځکه خلق د ورکو شوو ګډو په شان سرګردانه ګرځى. په هغوئ ځکه ظلم کيږى چې شپون يې نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21904, 'Zechariah 10:3', 'Zechariah', 10, 3, '&nbsp;”زما غصه د شپونکو خلاف زياته شوې ده، او زۀ به حکمرانانو له سزا ورکړم، ځکه چې مالِک خُدائ به د خپلې رمې حفاظت کوى، د يهوداه د قوم، او هغوئ به لکه د جنګ د فخر آس جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21905, 'Zechariah 10:4', 'Zechariah', 10, 4, '&nbsp;د يهوداه نه به د ګوټ کاڼے، د خېمې موږے، د جنګ لينده جوړه شى، د هغې نه به هر يو حکمران راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21906, 'Zechariah 10:5', 'Zechariah', 10, 5, '&nbsp;هغوئ به يو ځائ لکه د طاقتورو خلقو په شان په جنګ کښې دشمنان د کوڅې په خټو کښې د پښو لاندې کړى. ځکه چې مالِک خُدائ د هغوئ سره دے، هغوئ به جنګ وکړى او د آسونو سوارۀ به لاندې راوغورزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21907, 'Zechariah 10:6', 'Zechariah', 10, 6, '&nbsp;زۀ به د يهوداه خلق تکړه کړم او د يوسف قوم به بچ کړم. زۀ به هغوئ بيا آباد کړم ځکه چې زۀ په هغوئ رحم کوم. هغوئ به داسې وى لکه چې کله ما هغوئ نۀ وى رد کړى. ځکه چې زۀ مالِک خُدائ د هغوئ خُدائ پاک يم، او زۀ به د هغوئ دُعا ته جواب ورکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21908, 'Zechariah 10:7', 'Zechariah', 10, 7, '&nbsp;اِفرائيميان به لکه د جنګيالو په شان شى، او د هغوئ زړونه به داسې خوشحاله وى لکه چې مے يې څښلى وى. د هغوئ اولاد به دا وګورى او خوشحاله به وى، د هغوئ زړونه به په مالِک خُدائ کښې خوشحاله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21909, 'Zechariah 10:8', 'Zechariah', 10, 8, '&nbsp;زۀ به هغوئ ته شپيلے ووهم او يو ځائ ته به يې راغونډ کړم. يقيناً زۀ به هغوئ آزاد کړم، هغوئ به بې‌شمېره کړم څنګه چې مخکښې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21910, 'Zechariah 10:9', 'Zechariah', 10, 9, '&nbsp;اګر کۀ ما هغوئ په قومونو کښې خوارۀ وارۀ کړى دى خو په لرې مُلکونو کښې به هغوئ ما ياد ساتى. هغوئ او د هغوئ بچى به ژوندى پاتې شى، او واپس به راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21911, 'Zechariah 10:10', 'Zechariah', 10, 10, '&nbsp;زۀ به هغوئ واپس راولم د مِصر نه او هغوئ به د اسور نه راجمع کړم. زۀ به هغوئ راولم جِلعاد او لبنان ته، او هلته به د هغوئ ټولو دپاره کافى ځايونه نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21912, 'Zechariah 10:11', 'Zechariah', 10, 11, '&nbsp;هغوئ به د مصيبت د سمندر نه تېر شى، چپې وهونکے سمندر به خاموش شى، او د نيل درياب ژورې اوبۀ به اوچې شى. د اسور غرور به راښکته شى، او د مِصر شاهى طاقت به ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21913, 'Zechariah 10:12', 'Zechariah', 10, 12, '&nbsp;زۀ به هغوئ له په مالِک خُدائ کښې طاقت ورکړم، او د هغۀ په نوم به هغوئ روان وى،“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21914, 'Zechariah 11:1', 'Zechariah', 11, 1, '&nbsp;خپلې دروازې کولاو کړه، اے لبنانه، چې اور ستا د دِيار ونې وسوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21915, 'Zechariah 11:2', 'Zechariah', 11, 2, '&nbsp;فرياد وکړه، اے د نختر ونې، ځکه چې د دِيار ونې راغورزېدلې دى، هغه د شان او شوکت والا ونې تباه شوې دى. فرياد وکړئ، اے د بسن د څېړو ونو، ګڼ ځنګلونه هم ختم شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21916, 'Zechariah 11:3', 'Zechariah', 11, 3, '&nbsp;د قوم شپونکو فرياد ته غوږ ونيسئ، د هغوئ د څرن شنۀ ځايونه تباه شول. د زمرو غړمبار ته غوږ ونيسئ، د اُردن ګڼ ځنګلونه تباه شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21917, 'Zechariah 11:4', 'Zechariah', 11, 4, '&nbsp;مالِک خُدائ زما خُدائ پاک دا فرمائى، ”هغه ګډې وڅروه چې د حلالې دپاره نښه شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21918, 'Zechariah 11:5', 'Zechariah', 11, 5, '&nbsp;د دې اخستونکى دا حلالې کړى او سزا ورته مِلاو نۀ شى. چې څوک يې خرڅوى هغوئ وائى، د مالِک خُدائ ثناء صِفت دې وى، مونږ مالداره شُو. د دې خپل شپونکى په دې رحم نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21919, 'Zechariah 11:6', 'Zechariah', 11, 6, '&nbsp;نو زۀ به هم نور د دې مُلک په خلقو رحم ونۀ کړم،“ مالِک خُدائ فرمائى. ”زۀ به هر يو خپل ګاونډى ته او خپل بادشاه ته حواله کړم. هغوئ به په مُلک ظلم وکړى، او زۀ به دوئ د هغوئ د لاسونو نه بچ نۀ کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21920, 'Zechariah 11:7', 'Zechariah', 11, 7, '&nbsp;نو ما د هغه ګډو شپونتوب وکړو چې د حلالولو دپاره نښه کړے شوى دى، په خاص طور مظلومې ګډې. بيا ما دوه چوکې واخستې چې يوه ”فضل“ او بله ”اتفاق“ بلل کېده، او ما پرې د ګډو شپونتوب وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21921, 'Zechariah 11:8', 'Zechariah', 11, 8, '&nbsp;په يوه مياشت کښې ما د قوم د درې شپونکو نه ځان خلاص کړو. خو ګډو ما نه نفرت وکړو، او زۀ د هغوئ نه تنګ شوم', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21922, 'Zechariah 11:9', 'Zechariah', 11, 9, '&nbsp;او ومې وئيل، ”زۀ به نور ستاسو شپون نۀ يم. پرېږدئ چې کومې مرى هغه دې مړې شى، او چې کومې تباه کيږى هغه دې تباه شى. پرېږدئ چې کومې پاتې شى هغه دې د يو بل غوښې وخورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21923, 'Zechariah 11:10', 'Zechariah', 11, 10, '&nbsp;بيا ما خپله امسا واخستله چې نوم يې ”فضل“ وو او ماته مې کړه، او هغه لوظ مې مات کړو چې ما ټولو قومونو سره کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21924, 'Zechariah 11:11', 'Zechariah', 11, 11, '&nbsp;دا هم په هغه ورځ مات شو. او د ګډو سوداګرو چا چې ما ته کتل پوهه شول چې دا د مالِک خُدائ کلام دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21925, 'Zechariah 11:12', 'Zechariah', 11, 12, '&nbsp;ما هغوئ ته ووئيل، ”کۀ تاسو سوچ کوئ چې دا ښۀ دى، ما ته خپله مزدورى راکړئ، خو کۀ ښۀ نۀ وى، نو ځان سره يې کړئ.“ نو هغوئ ما له دېرش د سپينو زرو سيکې مزدورى راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21926, 'Zechariah 11:13', 'Zechariah', 11, 13, '&nbsp;او مالِک خُدائ ما ته وفرمائيل، ”دا په خزانه کښې ورغورزوه.“ دا اوچت قيمت دے کوم قيمت چې هغوئ زما ولګولو، بيا ما دا دېرش د سپينو زرو سيکې واخستلې او د مالِک خُدائ د کور په خزانه کښې مې وروغورزولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21927, 'Zechariah 11:14', 'Zechariah', 11, 14, '&nbsp;بيا ما خپله دوېمه امسا ماته کړه چې نوم يې ”اتفاقى“ وو، او د يهوداه او د اِسرائيل په مينځ کښې ورورولى مې ماته کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21928, 'Zechariah 11:15', 'Zechariah', 11, 15, '&nbsp;بيا مالِک خُدائ ما ته وفرمائيل، ”د کم عقل شپون سامان يو ځل بيا راواخله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21929, 'Zechariah 11:16', 'Zechariah', 11, 16, '&nbsp;ځکه چې زۀ يو شپون راولم په دې مُلک چې هغه به د ورک شوو پرواه نۀ کوى، يا به خوارۀ شوى نۀ لټوى، يا به زخمى شوو له شفا نۀ ورکوى، نۀ به صحتمندو له خوراک ورکوى، خو هغه به د څُرب ګډانو غوښه خورى او د دوئ سومونه به وشلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21930, 'Zechariah 11:17', 'Zechariah', 11, 17, '&nbsp;افسوس دې په بې‌کاره شپون وى، چې رمه پرېږدى. تُوره دې د هغۀ لاس او د هغۀ ښۍ سترګه ووهى. د هغۀ لاس دې مکمل اوچ شى، او د هغۀ ښۍ سترګه دې بلکل ړنده شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21931, 'Zechariah 12:1', 'Zechariah', 12, 1, '&nbsp;د بنى اِسرائيلو په حقله دا د مالِک خُدائ پېغام دے. د هغه مالِک خُدائ، چا چې آسمانونه خوارۀ کړى دى، چا چې د زمکې بنيادونه اېښى دى، او چا چې بنى آدم له ساه ورکړې ده، هغه فرمائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21932, 'Zechariah 12:2', 'Zechariah', 12, 2, '&nbsp;”زۀ به يروشلم نه د شرابو پياله جوړه کړم چې ګېرچاپېره قومونه يې په څښلو سره سرګردانه شى، کله چې هغوئ خپل فوجيان د يهوداه او يروشلم محاصره کولو دپاره رالېږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21933, 'Zechariah 12:3', 'Zechariah', 12, 3, '&nbsp;په هغه ورځ، کله چې د زمکې ټول قومونه د دې خلاف يو ځائ شى، زۀ به د يروشلم نه د ټولو قومونو دپاره يو نۀ خوځېدونکے کاڼے جوړ کړم. هر هغه څوک چې د دې د لرې کولو کوشش کوى هغوئ به خپل ځانونه زخمى کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21934, 'Zechariah 12:4', 'Zechariah', 12, 4, '&nbsp;په هغه ورځ به زۀ هر آس اوتر کړم او د دې سوارۀ به ليونى کړم،“ مالِک خُدائ فرمائى. ”زۀ به د يهوداه په قوم باندې نظر ساتم. خو زۀ به د دوئ د دشمنانو ټول آسونه ړاندۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21935, 'Zechariah 12:5', 'Zechariah', 12, 5, '&nbsp;بيا د يهوداه حکمرانان به په خپلو زړونو کښې وائى، د يروشلم خلق مضبوط دى، ځکه چې مالِک خُدائ ربُ الافواج د هغوئ خُدائ پاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21936, 'Zechariah 12:6', 'Zechariah', 12, 6, '&nbsp;په هغه ورځ به زۀ د يهوداه حکمرانان لکه د لرګو اور، لکه لمبه وهونکى مشعل چې د غنمو د ګېډۍ په مينځ کښې وى جوړ کړم. دا به ښى او ګس طرف ته ګېرچاپېره ټول خلق وسوزوى، خو يروشلم به په خپل ځائ روغ رمټ پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21937, 'Zechariah 12:7', 'Zechariah', 12, 7, '&nbsp;مالِک خُدائ به د يروشلم نه وړاندې نورو يهوديانو ته کاميابې ورکړى، تر دې چې د يروشلم خلقو او د داؤد شاهى خاندان ته د يهوداه نه زيات عزت مِلاو نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21938, 'Zechariah 12:8', 'Zechariah', 12, 8, '&nbsp;په هغه ورځ به مالِک خُدائ هغه خلق بچ کړى څوک چې په يروشلم کښې اوسيږى، نو په هغوئ کښې به د ټولو نه کمزورى د داؤد هومره طاقتور وى، او د داؤد اولاد به داسې وى لکه چې خُدائ پاک او لکه چې د مالِک خُدائ يوه فرښته په خپله د هغوئ نه وړاندې روانه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21939, 'Zechariah 12:9', 'Zechariah', 12, 9, '&nbsp;په هغه ورځ به زۀ د هغه ټولو قومونو تباه کول شروع کړم کوم چې په يروشلم حمله کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21940, 'Zechariah 12:10', 'Zechariah', 12, 10, '&nbsp;زۀ به د داؤد په اولاد او څوک چې په يروشلم کښې اوسيږى د فضل او دُعا روح نازل کړم. هغوئ به ما ته ګورى، هغه چا ته چې دوئ په نېزه وهلے دے، او هغوئ به د هغۀ دپاره داسې ماتم وکړى لکه چې څوک په خپل ايکې يو ماشوم ماتم کوى، او ډېر سخت به خفه شى لکه د چا چې اولنے زوئ مړ شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21941, 'Zechariah 12:11', 'Zechariah', 12, 11, '&nbsp;په هغه ورځ به په يروشلم کښې لوئ وير وى، داسې لکه د هددرمون وير چې د مِجدو په مېدان کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21942, 'Zechariah 12:12', 'Zechariah', 12, 12, '&nbsp;ټول مُلک به ماتم کوى، هره يوه قبيله به په خپله د خپلو ښځو نه جُدا يعنې، د داؤد د خاندان قبيله به خپلو ښځو نه جُدا، د ناتن قبيله به خپلو ښځو نه جُدا،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21943, 'Zechariah 12:13', 'Zechariah', 12, 13, '&nbsp;د ليوى قبيلې به د خپلو ښځو نه جُدا، د سِمعى قبيله به خپلو ښځو نه جُدا،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21944, 'Zechariah 12:14', 'Zechariah', 12, 14, '&nbsp;او هره پاتې شوې قبيله به ځان ځان له ماتم کوى او د دوئ ښځې به هم ځانله ماتم کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21945, 'Zechariah 13:1', 'Zechariah', 13, 1, '&nbsp;”په هغه ورځ به چينه د داؤد د خاندان او د يروشلم اوسېدونکو دپاره کولاو شى چې دوئ د ګناه او ناپاکۍ نه پاک کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21946, 'Zechariah 13:2', 'Zechariah', 13, 2, '&nbsp;په هغه ورځ به زۀ د بُتانو نومونه د مُلک نه ختم کړم، هغوئ به نور نۀ ياديږى،“ مالِک خُدائ ربُ الافواج فرمائى. ”زۀ به دروغژن پېغمبران او ناپاکه روحونه دواړه د مُلک نه ختم کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21947, 'Zechariah 13:3', 'Zechariah', 13, 3, '&nbsp;او کۀ اوس هم څوک پېشګوئې کوى، د هغۀ پلار او مور، چا نه چې هغه پېدا دے، به هغۀ ته وائى، تۀ به ضرور مړ شې، ځکه چې تا د مالِک خُدائ په نوم دروغ ووئيل. کله چې هغه پېشګوئې کوى د هغۀ خپل پلار مور به يې وڅيرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21948, 'Zechariah 13:4', 'Zechariah', 13, 4, '&nbsp;په هغه ورځ به پېغمبران په پېشګوئې کولو او په رويا بيانولو شرميږى. د پېغمبرانو په ببره چُوغه اچولو به څوک هم نۀ دوکه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21949, 'Zechariah 13:5', 'Zechariah', 13, 5, '&nbsp;هغه به وائى، زۀ پېغمبر نۀ يم. زۀ زميندار يم، زمکه د ځوانۍ نه زما روزګار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21950, 'Zechariah 13:6', 'Zechariah', 13, 6, '&nbsp;کۀ څوک ترې نه تپوس وکړى، دا زخمونه ستا په بدن باندې د څۀ دى؟ هغه به جواب ورکړى، دا زخمونه په ما باندې زما د ملګرى کور کښې لګېدلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21951, 'Zechariah 13:7', 'Zechariah', 13, 7, '&nbsp;اے تُورې، زما د شپونکى خلاف راپاڅه، د هغه سړى خلاف چې زما ملګرے دے.“ مالِک خُدائ ربُ الافواج فرمائى. ”زۀ به شپون ووهم، او ګډې به يې خورې ورې شى، او زۀ به خپل لاس د هغوئ خلاف اوږد کړم چې واړۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21952, 'Zechariah 13:8', 'Zechariah', 13, 8, '&nbsp;په ټول مُلک کښې،“ مالِک خُدائ فرمائى، ”په درېو کښې به دوه مړۀ او تباه شى، درېو کښې به يو پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21953, 'Zechariah 13:9', 'Zechariah', 13, 9, '&nbsp;دا درېمه برخه به زۀ اور کښې واچوم، زۀ به دوئ لکه د سپينو زرو په شان صفا کړم او لکه د سرو زرو به يې وآزمائيم. هغوئ به زما په نوم آواز وکړى او زۀ به هغوئ له جواب ورکړم، او زۀ به ووايم چې، دوئ زما خلق دى، او هغوئ به وائى، مالِک خُدائ زمونږ خُدائ پاک دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21954, 'Zechariah 14:1', 'Zechariah', 14, 1, '&nbsp;ګورئ، د مالِک خُدائ ورځ راروانه ده چې ستاسو مال به بلکل ستاسو په وړاندې لوټ کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21955, 'Zechariah 14:2', 'Zechariah', 14, 2, '&nbsp;زۀ به ټول قومونه راغونډ کړم چې د يروشلم خلاف جنګ وکړى، ښار به محاصره شى، کورونه به لوټ شى او ښځې به په زور بې‌عزته شى. نيم ښار به جلاوطن شى، خو نور پاتې خلق به د ښار نه بونۀ تلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21956, 'Zechariah 14:3', 'Zechariah', 14, 3, '&nbsp;بيا به مالِک خُدائ لاړ شى او د هغه قومونو خلاف به داسې جنګ وکړى، لکه څنګه چې هغۀ پخوا جنګ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21957, 'Zechariah 14:4', 'Zechariah', 14, 4, '&nbsp;په هغه ورځ به د هغۀ پښې د زيتُونو په غر د يروشلم مشرق طرف ته ودريږى. او د زيتُونو غر به د مشرق نه تر مغرب پورې په مينځ نيم شى، يوه لويه وادى به جوړه شى، دا غر به نيم د شمال طرف ته او نيم د جنوب طرف ته وښويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21958, 'Zechariah 14:5', 'Zechariah', 14, 5, '&nbsp;بيا به تاسو زما د غرۀ په وادۍ کښې وتښتئ، ځکه دا به تر آضل پورې رسېدلې وى. تاسو به داسې وتښتئ لکه څنګه چې تاسو د يهوداه د بادشاه عُزياه په ورځو کښې د زلزلې نه وتښتېدلئ. بيا مالِک خُدائ زما خُدائ پاک به راشى، او ټولې پاکې فرښتې به هغۀ سره راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21959, 'Zechariah 14:6', 'Zechariah', 14, 6, '&nbsp;په هغه ورځ به نۀ رڼا او نۀ يخ او نۀ کنګل وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21960, 'Zechariah 14:7', 'Zechariah', 14, 7, '&nbsp;دا به يو بې‌مثاله ورځ وى، نۀ به ورځ وى نۀ به شپه وى، مالِک خُدائ ته به د دې پته وى. د ماښام په وخت کښې به هم رڼا وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21961, 'Zechariah 14:8', 'Zechariah', 14, 8, '&nbsp;په هغه ورځ به د ژوند اوبۀ د يروشلم نه بهيږى، نيمې به د مشرق سمندر ته او نيمې به د مغرب سمندر ته، په ګرمۍ او يخنۍ کښې بهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21962, 'Zechariah 14:9', 'Zechariah', 14, 9, '&nbsp;مالِک خُدائ به په ټوله زمکه بادشاه وى، په هغه ورځ به صرف يو مالِک خُدائ وى، او صرف د هغۀ نوم به وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21963, 'Zechariah 14:10', 'Zechariah', 14, 10, '&nbsp;ټول مُلک، د جبع نه تر رِمون پورې، د يروشلم جنوب طرف ته، به لکه د عرابه د وادۍ په شان شى. خو يروشلم به بيا اوچت شى او په خپل ځائ به ودريږى، د بنيامين د دروازې نه تر د زړې دروازې پورې، د ګوټ دروازې پورې، او د حنن‌ايل د برج نه تر د شاهى انګورو د لنګرو پورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21964, 'Zechariah 14:11', 'Zechariah', 14, 11, '&nbsp;دا به بيا آباد شى، دا به بيا هيڅکله هم تباه نۀ شى. يروشلم به محفوظ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21965, 'Zechariah 14:12', 'Zechariah', 14, 12, '&nbsp;دا هغه وبا ده چې مالِک خُدائ به په دې هغه خلق مړۀ کړى چا چې د يروشلم خلاف جنګ کړے وو. د هغوئ غوښې به سخا شى چې لا دوئ په خپلو پښو ولاړ وى، د دوئ سترګې به په خپل ځائ سخا شى، او د دوئ ژبې به د دوئ په خُلو کښې سخا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21966, 'Zechariah 14:13', 'Zechariah', 14, 13, '&nbsp;په هغه ورځ به مالِک خُدائ خلق په لوئ درد اخته کړى. هر سړے به د بل لاس راونيسى، او هغوئ به په يو بل حمله وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21967, 'Zechariah 14:14', 'Zechariah', 14, 14, '&nbsp;تر دې چې يهوداه او يروشلم به په خپلو کښې جنګ کوى. د ګېرچاپېره ټولو قومونو دولت به راغونډ کړے شى، چې په کښې به په لوئ مِقدار سرۀ زر او سپين زر او جامې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21968, 'Zechariah 14:15', 'Zechariah', 14, 15, '&nbsp;هم دغه شان به په آسونو او قچرو، اوښانو، خرونو او چې څومره ځناور په هغه ځائ کښې دى افت نازل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21969, 'Zechariah 14:16', 'Zechariah', 14, 16, '&nbsp;بيا به د ټولو قومونو پاتې ژوندى کسان چا چې په يروشلم حمله کړې وه کال په کال د بادشاه، مالِک خُدائ ربُ الافواج عبادت ته هلته ځى، او د جونګړو اختر به کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21970, 'Zechariah 14:17', 'Zechariah', 14, 17, '&nbsp;خو کۀ هر قوم يروشلم ته د تلو او د بادشاه مالِک خُدائ ربُ الافواج د عبادت نه اِنکار وکړى، نو په هغوئ به باران نۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21971, 'Zechariah 14:18', 'Zechariah', 14, 18, '&nbsp;کۀ مِصريان هلته لاړ نۀ شى او خپل ځانونه هلته حاضر نۀ کړى، نو په هغوئ به باران نۀ کيږى. مالِک خُدائ به په هغوئ هغه وبا نازله کړى چې مالِک خُدائ يې په هغه قومونو رالېږى څوک چې د جونګړو اختر لمانځلو له نۀ ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21972, 'Zechariah 14:19', 'Zechariah', 14, 19, '&nbsp;دا به د مِصر او د هغه ټولو قومونو سزا وى چې څوک د جونګړو اختر لمانځلو له نۀ ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21973, 'Zechariah 14:20', 'Zechariah', 14, 20, '&nbsp;په هغه ورځ به د آسونو په ګونګرو باندې هم ليکلى وى ”مالِک خُدائ ته مقدس کړے شوى“ او د پخلى دېګونه د مالِک خُدائ په کور کښې به لکه د هغه مقدسو لوښو په شان وى چې د قربان‌ګاه په وړاندې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21974, 'Zechariah 14:21', 'Zechariah', 14, 21, '&nbsp;هر يو لوښے به په يروشلم او يهوداه کښې مالِک خُدائ ربُ الافواج ته مقدس وى. او هغوئ ټول چې قربانۍ کولو له راغلى دى هغوئ به څۀ لوښى واخلى او په کښې به پخلى کولے شى. او په هغه ورځ به د مالِک خُدائ ربُ الافواج په کور کښې يو کنعانى سوداګر هم پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21975, 'Malachi 1:1', 'Malachi', 1, 1, '&nbsp;دا هغه پېغام دے کوم چې مالِک خُدائ د ملاکى په وسيله بنى اِسرائيلو له ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21976, 'Malachi 1:2', 'Malachi', 1, 2, '&nbsp;”ما تاسو سره مينه کړې ده،“ مالِک خُدائ فرمائى. ”خو تاسو تپوس کوئ چې، تا مونږ سره څنګه مينه کړې ده؟“ مالِک خُدائ په جواب کښې وفرمائيل، ”آيا عِيسو د يعقوب ورور نۀ وو څۀ؟ بيا هم ما يعقوب سره مينه وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21977, 'Malachi 1:3', 'Malachi', 1, 3, '&nbsp;خو عِيسو يعنې د ادوميانو پلار نيکۀ ما رد کړو، او ما د هغوئ غرونه شاړ کړل او د هغوئ ميراث مې د بيابان ګيدړانو ته پرېښودلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21978, 'Malachi 1:4', 'Malachi', 1, 4, '&nbsp;ادوميان وائى چې، ”اګر کۀ مونږ تباه کړے شوى يُو، خو مونږ به دا کنډرې بيا جوړې کړُو.“ خو مالِک خُدائ ربُ الافواج دا فرمائى چې، ”هغوئ دا جوړولے شى، خو زۀ به يې تباه کړم. دې ته به د بدعملۍ مُلک وئيلے کيږى، او خلق به يې همېشه د خُدائ پاک د لعنت لاندې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21979, 'Malachi 1:5', 'Malachi', 1, 5, '&nbsp;کله چې تاسو دا تباهى په خپلو سترګو وګورئ نو وبه وايئ چې، مالِک خُدائ د اِسرائيل د سرحدونو نه بهر هم خپله لوئى ښکاره کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21980, 'Malachi 1:6', 'Malachi', 1, 6, '&nbsp;مالِک خُدائ ربُ الافواج اِمامانو ته فرمائى چې، ”يو زوئ د خپل پلار عزت کوى، او نوکر د خپل مالِک. کۀ چرې زۀ پلار يم، نو زما هغه عزت چرته دے؟ کۀ چرې زۀ مالِک يم، نو زما هغه احترام چرته دے؟ اے اِمامانو، خو دا تاسو يئ چې زما د نوم سپکاوے کوئ. خو تاسو تپوس کوئ چې، مونږ څنګه ستا د نوم سپکاوے کړے دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21981, 'Malachi 1:7', 'Malachi', 1, 7, '&nbsp;تاسو زما په قربان‌ګاه ناپاکه خوراک کېښودو. او بيا هم تاسو تپوس کوئ چې تۀ مونږ په څۀ ناپاک کړے يې؟ په دې چې تاسو ووئيل چې د مالِک خُدائ قربان‌ګاه ناپاکه ده زما د قربان ګاه سپکاوے مو وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21982, 'Malachi 1:8', 'Malachi', 1, 8, '&nbsp;کله چې تاسو ړاندۀ څاروى د قربانۍ دپاره راولئ، آيا دا غلط کار نۀ دے؟ کله چې تاسو ګوډ يا بيمار څاروى قربانى کوئ، آيا دا غلط کار نۀ دے څۀ؟ کۀ تاسو دا کوشش وکړئ چې دا خپل حکمران ته پېش کړئ، آيا هغه به تاسو نه خوشحاله شى څۀ؟ آيا هغه به تاسو قبول کړى؟“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21983, 'Malachi 1:9', 'Malachi', 1, 9, '&nbsp;”اوس خُدائ پاک ته سوال زارى کوئ چې په مونږ مهربان شى. ستاسو نه په داسې قربانۍ پېش کولو، آيا هغه به تاسو قبول کړى؟“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21984, 'Malachi 1:10', 'Malachi', 1, 10, '&nbsp;”اے کاش چې په تاسو کښې يو کس د عبادتخانې دروازې بندې کړى، نو چې تاسو نور بې‌فائدې اور زما په قربان‌ګاه بل نۀ کړئ. زۀ تاسو نه خوشحاله نۀ يم،“ مالِک خُدائ ربُ الافواج فرمائى، ”او زۀ به ستاسو د لاسونو نه نذرانې قبولې نۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21985, 'Malachi 1:11', 'Malachi', 1, 11, '&nbsp;زما نوم به د قومونو په مينځ کښې عظيم وى، د نمر راختو نه تر نمر پرېوتو پورې. په هر ځائ کښې به خوشبودارې او پاکې نذرانې ما ته راوړے شى، ځکه چې زما نوم به د قومونو په مينځ کښې عظيم وى،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21986, 'Malachi 1:12', 'Malachi', 1, 12, '&nbsp;”خو تاسو زما د نوم بې‌حرمتى کوئ په دې وئيلو سره چې د مالِک خُدائ قربان‌ګاه ناپاکه ده، او د دې خوراک بې‌اهميته دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21987, 'Malachi 1:13', 'Malachi', 1, 13, '&nbsp;او تاسو وايئ چې، دا څومره بوج دے. او پوکى وهئ او د دې نه نفرت کوئ،“ مالِک خُدائ ربُ الافواج فرمائى. ”کله چې تاسو د غلا، ګوډ يا بيمار څاروى راولئ او د قربانۍ په طور يې پېش کړئ، آيا زۀ دا ستاسو د لاسونو نه قبول کړم څۀ؟“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21988, 'Malachi 1:14', 'Malachi', 1, 14, '&nbsp;”لعنت دې وى په هغه دوکه باز باندې چې په رمه کښې يې څُرب نر څاروے وى او نذرونه يې منلې وى، خو مالِک ته مات ګوډ څاروے قربانى کړى.“ نو مالِک خُدائ ربُ الافواج فرمائى چې، ”زۀ لوئ بادشاه يم، او په قومونو کښې خلق زما د نوم نه يريږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21989, 'Malachi 2:1', 'Malachi', 2, 1, '&nbsp;”ګورئ اوس دا حکم ستاسو دپاره دے، اے اِمامانو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21990, 'Malachi 2:2', 'Malachi', 2, 2, '&nbsp;کۀ تاسو غوږ نۀ نيسئ، او کۀ تاسو د خپل زړۀ نه زما د نوم احترام نۀ کوئ،“ مالِک خُدائ ربُ الافواج فرمائى، ”زۀ به په تاسو لعنت نازل کړم، او زۀ به ستاسو نعمتونه لعنتى کړم. په اصل کښې ما هغوئ د اول نه لعنتى کړى دى، ځکه چې تاسو د خپل زړۀ نه زما احترام ونۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21991, 'Malachi 2:3', 'Malachi', 2, 3, '&nbsp;ستاسو په وجه به زۀ ستاسو اولاد ورټم، زۀ به ستاسو په مخونو ستاسو د اختر د قربانو ګند واچوم، او تاسو به دې سره بهر وغورزولے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21992, 'Malachi 2:4', 'Malachi', 2, 4, '&nbsp;او تاسو به پوهه شئ چې ما تاسو ته دا حکم درلېږلے دے چې زما لوظ به د ليويانو سره جارى وى،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21993, 'Malachi 2:5', 'Malachi', 2, 5, '&nbsp;”زما لوظ هغوئ سره وو، د ژوند او امن لوظ، او ما دا هغوئ ته ورکړو چې زما تعظيم وکړى، او هغوئ زما عزت وکړو او زما د نوم د دهشت نه ويرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21994, 'Malachi 2:6', 'Malachi', 2, 6, '&nbsp;رښتينے شريعت د هغوئ په خولۀ کښې وو او هيڅ دروغ د هغوئ په شونډو نۀ وو. هغوئ ما سره په امن او صداقت روان وُو، او ډېر يې د ګناه نه واړول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21995, 'Malachi 2:7', 'Malachi', 2, 7, '&nbsp;د اِمام د خولې دا فرض دى چې صحيح تعليم خور کړى، او د هغۀ د خولې نه دې خلق د شريعت لټون وکړى، ځکه چې هغه د مالِک خُدائ ربُ الافواج پېغام رسوونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21996, 'Malachi 2:8', 'Malachi', 2, 8, '&nbsp;خو تاسو اِمامان د خپلې صحيح لارې نه واوړېدئ او ستاسو د شريعت په وجه ډېرو تيندک خوړلے دے. د ليويانو سره زما شوے لوظ تا مات کړو،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21997, 'Malachi 2:9', 'Malachi', 2, 9, '&nbsp;”نو په دې وجه ما تۀ د ټولو خلقو په وړاندې سپک او عاجز کړې، ځکه چې تا زما په طريقو عمل ونۀ کړو خو د شريعت په مسئلو کښې دې طرفدارى وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21998, 'Malachi 2:10', 'Malachi', 2, 10, '&nbsp;آيا زمونږ ټولو پلار يو نۀ دے؟ آيا يو خُدائ پاک مونږ جوړ کړى نۀ يُو؟ مونږ بيا ولې په خپلو کښې د يو بل سره په بې‌وفائى کولو د خپل پلار نيکۀ د لوظ بې‌احترامى کوُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21999, 'Malachi 2:11', 'Malachi', 2, 11, '&nbsp;يهوداه بې‌ايمانى وکړه. يو حرام عمل يې په اِسرائيل يعنې يروشلم کښې کړے وو، د هغه پاک کور چې مالِک خُدائ ورسره مينه کوله د هغه ښځو سره په وادۀ کولو چې بُت پرسته وې، يهوداه بې‌احترامى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22000, 'Malachi 2:12', 'Malachi', 2, 12, '&nbsp;د هغه سړى دپاره چې څوک داسې کوى، چې هغه څوک هم وى، مالِک خُدائ دې هغه د بنى اِسرائيلو د قوم نه وشړى. کۀ هغه مالِک خُدائ ربُ الافواج ته نذرانې هم راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');